create table public.invoices (id uuid primary key default gen_random_uuid(), store_id uuid not null, order_id uuid not null, invoice_number text not null, status text not null default 'issued' check(status in ('issued','void')), issued_at timestamptz not null default now(), document_url text, subtotal_minor bigint not null check(subtotal_minor>=0), tax_minor bigint not null check(tax_minor>=0), total_minor bigint not null check(total_minor>=0), currency char(3) not null, snapshot jsonb not null, foreign key(store_id,order_id) references public.orders(store_id,id), unique(store_id,invoice_number), unique(order_id));
